    el.parentElement.appendChild(m); m.querySelector('button')?.focus();
    const kapat = (e) => { if (!m.contains(e.target) && e.target !== el) { m.remove(); el.setAttribute('aria-expanded', 'false'); document.removeEventListener('click', kapat); } };
