  EYLEM['izin-ekle'] = () => { const k = P.katmanAc({ baslik: 'SMS kampanya izni ekle', govde: `<p class="metin-ikincil">İzin, kaynağıyla birlikte kaydedilir. Sözlü onay kaynak olarak kabul edilmez.</p><div class="alan" style="margin-top:12px"><label class="alan__etiket" for="iz-k">İznin kaynağı</label><select id="iz-k"><option value="">Seçin</option><option>Kâğıt üzerinde imzalı form</option><option>Müşterinin SMS ile onayı</option></select><p class="alan__ipucu">“Online randevu formu” kaynağını sistem kendisi yazar.</p></div>`, alt: `<button class="dugme dugme--ikincil" data-katman-kapat>Vazgeç</button><button class="dugme dugme--birincil" data-k>İzni kaydet</button>` }); k.kok.querySelector('[data-k]').onclick = () => { if (!k.kok.querySelector('#iz-k').value) { P.bildir('İznin kaynağını seçin.', { tur: 'hata' }); return; } k.kapat(); P.bildir('Kampanya izni kaydedildi.'); }; };
  EYLEM['izin-kaldir'] = () => P.bildir('Kampanya izni kaldırıldı.', { geriAl: () => P.bildir('Kampanya izni geri yüklendi.') });
  EYLEM['seans-dus'] = () => P.bildir('Seans düşüldü. 2 seans kaldı.');
  EYLEM['paket-sat'] = () => { const k = P.katmanAc({ baslik: 'Paket sat', govde: `<div class="yigin yigin--8" data-tekli role="radiogroup" aria-label="Paket">${V.PAKETLER.map((p, i) => `<button class="secim-kart" aria-pressed="${i === 0}"><span class="secim-kart__ana"><span class="orta">${p.ad}</span><span class="metin-14 metin-soluk">${p.seans} seans · ${p.gecerlilik} geçerli</span></span><span class="secim-kart__sag sayi orta">${para(p.fiyat)}</span></button>`).join('')}</div><fieldset class="alan" style="border:0;padding:0;margin:16px 0 0"><legend class="alan__etiket" style="margin-bottom:6px">Ödeme yöntemi</legend><div class="parcali parcali--tam" data-tekli><button aria-pressed="true">Nakit</button><button aria-pressed="false">Kart</button></div></fieldset>`, alt: `<button class="dugme dugme--ikincil" data-katman-kapat>Vazgeç</button><button class="dugme dugme--birincil" data-s>Paket sat</button>` }); k.kok.querySelector('[data-s]').onclick = (e) => P.isle(e.currentTarget, 'Paket satılıyor…', () => { k.kapat(); P.bildir('Paket satıldı.'); }); };

