      <form class="kart" style="padding:16px;margin-top:12px"><div class="alan"><label class="alan__etiket" for="ks-a">Alerjiler</label><textarea id="ks-a">Lateks (kurgusal örnek)</textarea></div><div class="alan"><label class="alan__etiket" for="ks-i">Kullandığı ilaçlar</label><textarea id="ks-i">Yok</textarea></div><div class="dugme-sirasi" style="margin-top:16px;justify-content:flex-end"><button class="dugme dugme--birincil" type="button" onclick="P.bildir('Değişiklikler kaydedildi.')">Kaydet</button></div></form>
